namespace native = pv_lio_plus::i_octree_native;
namespace fixture = i_octree_numeric_fixture;
using Key = std::array<std::uint32_t, 3>;
using Multiset = std::multiset<Key>;

static_assert(sizeof(float) == 4 && sizeof(double) == 8, "IEEE storage sizes required");
static_assert(std::numeric_limits<float>::is_iec559 && std::numeric_limits<float>::digits == 24,
              "IEEE binary32 required");
static_assert(std::numeric_limits<double>::is_iec559 && std::numeric_limits<double>::digits == 53,
              "IEEE binary64 required");
static_assert(FLT_EVAL_METHOD == 0, "Each operation must round at its declared width");

template <class Float, class UInt>
Float Decode(UInt bits)
{
    static_assert(sizeof(Float) == sizeof(UInt), "bit widths must match");
    Float value;
    std::memcpy(&value, &bits, sizeof(value));
    return value;
}

template <class UInt, class Float>
UInt Bits(Float value)
{
    static_assert(sizeof(Float) == sizeof(UInt), "bit widths must match");
    UInt bits;
    std::memcpy(&bits, &value, sizeof(bits));
    return bits;
}

double Double(std::uint64_t bits) { return Decode<double>(bits); }
float Float(std::uint32_t bits) { return Decode<float>(bits); }

native::Point3f Point(const fixture::FloatPoint &p)
{
    return {Float(p.xyz[0]), Float(p.xyz[1]), Float(p.xyz[2])};
}

native::Point3d Point(const fixture::DoublePoint &p)
{
    return {Double(p.xyz[0]), Double(p.xyz[1]), Double(p.xyz[2])};
}

Key PointKey(const native::Point3f &p)
{
    return {{Bits<std::uint32_t>(p.x), Bits<std::uint32_t>(p.y), Bits<std::uint32_t>(p.z)}};
}

Key PointKey(const fixture::FloatPoint &p) { return {{p.xyz[0], p.xyz[1], p.xyz[2]}}; }

void CheckEnvironment()
{
    ASSERT_EQ(std::fegetround(), FE_TONEAREST);
#if defined(__SSE__)
    // DAZ changes inputs and FTZ changes outputs, including the subnormal cases.
    ASSERT_EQ(_mm_getcsr() & ((1u << 6) | (1u << 15)), 0u);
#endif
    ASSERT_NO_THROW(native::require_numeric_environment());
}

void ExpectBits(double actual, std::uint64_t expected)
{
    EXPECT_EQ(Bits<std::uint64_t>(actual), expected) << std::hexfloat << actual << " expected " << Double(expected);
}

TEST(IOctreeNumericOracle, IndependentScalarKernelBitPatterns)
{
    ASSERT_NO_FATAL_FAILURE(CheckEnvironment());
    for (const auto &c : fixture::scalar_cases)
    {
        SCOPED_TRACE(c.name);
        ExpectBits(native::distance_squared(Point(c.point), Point(c.query)), c.distance);
    }
}

TEST(IOctreeNumericOracle, IndependentRadiusSquaredAndInvalidThresholds)
{
    ASSERT_NO_FATAL_FAILURE(CheckEnvironment());
    native::Octree tree;
    tree.initialize({native::Point3d{0, 0, 0}});
    for (const auto &c : fixture::radius_cases)
    {
        SCOPED_TRACE(c.radius);
        ExpectBits(native::radius_squared(Double(c.radius)), c.threshold);
    }
    for (const auto bits : fixture::invalid_radii)
    {
        SCOPED_TRACE(bits);
        EXPECT_ANY_THROW(native::radius_squared(Double(bits)));
        std::vector<native::Neighbor> output{{{123, 123, 123}, 123}};
        EXPECT_ANY_THROW(tree.radius({0, 0, 0}, Double(bits), output));
        EXPECT_TRUE(output.empty());  // Outputs are cleared on entry, also on rejection.
    }
}

TEST(IOctreeNumericOracle, IndependentAabbBoundsAndEveryContainedPoint)
{
    ASSERT_NO_FATAL_FAILURE(CheckEnvironment());
    for (const auto &c : fixture::box_cases)
    {
        SCOPED_TRACE(c.name);
        const native::Aabb box{Point(c.lo), Point(c.hi)};
        const auto actual = native::aabb_distance_bounds(box, Point(c.query));
        ExpectBits(actual.lower, c.lower);
        ExpectBits(actual.upper, c.upper);
        for (std::size_t index = c.first; index < c.first + c.count; ++index)
        {
            const auto &point = fixture::box_points[index];
            // The expected distance comes from Fraction, not distance_squared.
            EXPECT_LE(actual.lower, Double(point.distance));
            EXPECT_GE(actual.upper, Double(point.distance));
            // Also link the scalar kernel to the independent contained-point oracle.
            ExpectBits(native::distance_squared(Point(point.point), Point(c.query)), point.distance);
        }
    }
}

using NodePoints = std::vector<std::vector<Key>>;

NodePoints CheckStructure(const std::vector<native::DebugNode> &nodes, const Multiset &expected)
{
    NodePoints descendants(nodes.size());
    if (expected.empty())
    {
        EXPECT_TRUE(nodes.empty());
        return descendants;
    }
    EXPECT_FALSE(nodes.empty());
    if (nodes.empty()) return descendants;
    std::vector<unsigned char> color(nodes.size(), 0);
    std::function<void(std::size_t)> visit = [&](std::size_t index)
    {
        EXPECT_EQ(color[index], 0u) << "cycle or shared child at " << index;
        if (color[index] != 0) return;
        color[index] = 1;
        const auto &node = nodes[index];
        bool leaf = true;
        for (const int child : node.children)
        {
            EXPECT_GE(child, -1);
            if (child < 0) continue;
            leaf = false;
            EXPECT_LT(static_cast<std::size_t>(child), nodes.size());
            if (static_cast<std::size_t>(child) >= nodes.size()) continue;
            // Public debug contract specifies depth-first node order.
            EXPECT_GT(static_cast<std::size_t>(child), index);
            if (static_cast<std::size_t>(child) <= index || color[child] != 0) continue;
            visit(static_cast<std::size_t>(child));
            descendants[index].insert(descendants[index].end(), descendants[child].begin(), descendants[child].end());
        }
        if (leaf)
        {
            EXPECT_FALSE(node.points.empty());
            for (const auto &p : node.points) descendants[index].push_back(PointKey(p));
        }
        else
        {
            EXPECT_TRUE(node.points.empty());
        }
        EXPECT_FALSE(descendants[index].empty());
        if (!descendants[index].empty())
        {
            const float lo[3] = {node.bounds.lo.x, node.bounds.lo.y, node.bounds.lo.z};
            const float hi[3] = {node.bounds.hi.x, node.bounds.hi.y, node.bounds.hi.z};
            for (int axis = 0; axis < 3; ++axis)
            {
                float minimum = Float(descendants[index][0][axis]);
                float maximum = minimum;
                for (const auto &p : descendants[index])
                {
                    minimum = std::min(minimum, Float(p[axis]));
                    maximum = std::max(maximum, Float(p[axis]));
                    EXPECT_LE(lo[axis], Float(p[axis]));
                    EXPECT_GE(hi[axis], Float(p[axis]));
                }
                // Zero signs are interchangeable as extrema, unlike point identity.
                EXPECT_EQ(lo[axis], minimum);
                EXPECT_EQ(hi[axis], maximum);
            }
        }
        color[index] = 2;
    };
    visit(0);
    EXPECT_EQ(Multiset(descendants[0].begin(), descendants[0].end()), expected);
    for (std::size_t index = 0; index < color.size(); ++index)
        EXPECT_EQ(color[index], 2u) << "unreachable debug node " << index;
    return descendants;
}

void CheckQueries(const native::Octree &tree, std::size_t scene_index)
{
    const auto &scene = fixture::scenes[scene_index];
    SCOPED_TRACE(scene.name);
    Multiset expected_points;
    for (std::size_t index = scene.first; index < scene.first + scene.count; ++index)
        expected_points.insert(PointKey(fixture::tree_points[index].stored));
    EXPECT_EQ(tree.size(), scene.count);
    Multiset snapshot;
    for (const auto &p : tree.snapshot()) snapshot.insert(PointKey(p));
    EXPECT_EQ(snapshot, expected_points);  // Includes duplicates and signed-zero representations.
    const auto nodes = tree.debug_nodes();
    const auto descendants = CheckStructure(nodes, expected_points);

    for (const auto &query : fixture::queries)
    {
        if (query.scene != scene_index) continue;
        SCOPED_TRACE(query.name);
        ASSERT_EQ(query.count, scene.count);
        std::vector<std::uint64_t> ordered;
        std::map<Key, std::uint64_t> point_distance;
        Multiset expected_radius;
        for (std::size_t index = 0; index < scene.count; ++index)
        {
            const auto key = PointKey(fixture::tree_points[scene.first + index].stored);
            const auto d = fixture::query_distances[query.first + index];
            ordered.push_back(d);
            const auto inserted = point_distance.emplace(key, d);
            EXPECT_EQ(inserted.first->second, d);
            // Positive IEEE bit order is exact; no production radius math here.
            if (d < query.threshold) expected_radius.insert(key);
        }
        std::sort(ordered.begin(), ordered.end());
        const auto count = std::min(static_cast<std::size_t>(query.k), scene.count);
        ordered.resize(count);
        std::vector<native::Neighbor> output{{{123, 123, 123}, 123}};
        EXPECT_EQ(tree.knn(Point(query.point), query.k, output), count);
        ASSERT_EQ(output.size(), count);
        auto available = expected_points;
        for (std::size_t index = 0; index < output.size(); ++index)
        {
            const auto key = PointKey(output[index].point);
            auto item = available.find(key);
            EXPECT_NE(item, available.end());
            if (item != available.end()) available.erase(item);
            const auto expected_distance = point_distance.find(key);
            EXPECT_NE(expected_distance, point_distance.end());
            if (expected_distance != point_distance.end())
                ExpectBits(output[index].distance_squared, expected_distance->second);
            // Equal-distance identity is intentionally not prescribed.
            ExpectBits(output[index].distance_squared, ordered[index]);
        }
        output = {{{123, 123, 123}, 123}};
        EXPECT_EQ(tree.radius(Point(query.point), Double(query.radius), output), expected_radius.size());
        ASSERT_EQ(output.size(), expected_radius.size());
        Multiset radius_points;
        for (const auto &neighbor : output)
        {
            const auto key = PointKey(neighbor.point);
            radius_points.insert(key);
            const auto expected_distance = point_distance.find(key);
            EXPECT_NE(expected_distance, point_distance.end());
            if (expected_distance != point_distance.end())
                ExpectBits(neighbor.distance_squared, expected_distance->second);
        }
        EXPECT_EQ(radius_points, expected_radius);  // Radius order is unspecified.

        for (std::size_t node = 0; node < nodes.size(); ++node)
        {
            const auto bound = native::aabb_distance_bounds(nodes[node].bounds, Point(query.point));
            EXPECT_TRUE(std::isfinite(bound.lower));
            EXPECT_TRUE(std::isfinite(bound.upper));
            EXPECT_GE(bound.lower, 0.0);
            EXPECT_LE(bound.lower, bound.upper);
            for (const auto &key : descendants[node])
            {
                const auto expected_distance = point_distance.find(key);
                ASSERT_NE(expected_distance, point_distance.end());
                EXPECT_LE(bound.lower, Double(expected_distance->second));
                EXPECT_GE(bound.upper, Double(expected_distance->second));
            }
        }
    }
    std::vector<native::Neighbor> output{{{123, 123, 123}, 123}};
    EXPECT_ANY_THROW(tree.knn({0, 0, 0}, -1, output));
    EXPECT_TRUE(output.empty());
}

TEST(IOctreeNumericOracle, IndependentTreeQueriesAndEveryAncestorBoundsAfterInitialize)
{
    ASSERT_NO_FATAL_FAILURE(CheckEnvironment());
    for (std::size_t scene_index = 0; scene_index < std::size(fixture::scenes); ++scene_index)
    {
        const auto &scene = fixture::scenes[scene_index];
        native::Config config;
        config.bucket_size = 4;
        native::Octree tree(config);
        std::vector<native::Point3d> input;
        for (std::size_t index = scene.first; index < scene.first + scene.count; ++index)
            input.push_back(Point(fixture::tree_points[index].input));
        ASSERT_NO_THROW(tree.initialize(input)) << scene.name;
        CheckQueries(tree, scene_index);
    }
}

TEST(IOctreeNumericOracle, SameIndependentReferenceAfterIncrementalGrowth)
{
    ASSERT_NO_FATAL_FAILURE(CheckEnvironment());
    for (std::size_t scene_index = 0; scene_index < std::size(fixture::scenes); ++scene_index)
    {
        const auto &scene = fixture::scenes[scene_index];
        native::Config config;
        config.bucket_size = 4;
        native::Octree tree(config);
        tree.initialize({});
        for (std::size_t index = scene.first; index < scene.first + scene.count; ++index)
        {
            ASSERT_NO_THROW(tree.update({Point(fixture::tree_points[index].input)}, false))
                << scene.name << " input index " << index - scene.first;
        }
        CheckQueries(tree, scene_index);
    }
}
